={
  "q": "{{ $fromAI('query', 'The search query string for finding building code information. Be specific and include the city, state, and code type.', 'string') }}",
  "num": 10
}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "executive_summary": {
      "type": "string",
      "description": "2-3 sentence overview of the current code status for this jurisdiction."
    },
    "base_code": {
      "type": "string",
      "description": "The base code adopted, e.g. '2021 Uniform Plumbing Code'."
    },
    "adopting_authority": {
      "type": "string",
      "description": "The body that adopted it, e.g. 'Washington State Building Code Council'."
    },
    "state_code_reference": {
      "type": "string",
      "description": "State administrative code reference, e.g. 'Chapter 51-56 WAC'."
    },
    "local_amendments": {
      "type": "string",
      "description": "Summary of city-specific amendments, or 'None found' if not located."
    },
    "results": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "properties": {
          "title": { "type": "string" },
          "link": { "type": "string" },
          "snippet": { "type": "string" },
          "source_type": {
            "type": "string",
            "enum": ["city", "state", "publisher", "other"]
          }
        },
        "required": ["title", "link", "snippet"]
      }
    }
  },
  "required": ["executive_summary", "base_code", "adopting_authority", "local_amendments", "results"]
}

parameters.jsCode:
const raw = $input.first().json;
const ai = raw?.output ?? raw;
const intermediateSteps = raw?.intermediateSteps ?? null;

const PUBLISHER_DOMAINS = [
  'codepublishing.com',
  'municode.com',
  'ecode360.com',
  'iccsafe.org'
];

function hostOf(url) {
  try { return new URL(url).hostname.toLowerCase(); }
  catch { return ''; }
}

function isPublisher(host) {
  return PUBLISHER_DOMAINS.some(d => host === d || host.endsWith('.' + d));
}

function isAllowed(host) {
  if (!host) return false;
  if (host.endsWith('.gov') || host.endsWith('.us')) return true;
  return isPublisher(host);
}

function retag(host, modelTag) {
  if (isPublisher(host)) return 'publisher';
  if (host.endsWith('.gov') || host.endsWith('.us')) {
    return (modelTag === 'state' || modelTag === 'city') ? modelTag : 'city';
  }
  return 'other';
}

const rawResults = Array.isArray(ai?.results) ? ai.results : [];
const seen = new Set();
const cleaned = [];
const all = [];  // track all unique URLs regardless of domain
let dropped = 0;

for (const r of rawResults) {
  const url = String(r?.link || '').trim();
  if (!url) { dropped++; continue; }
  if (seen.has(url)) { dropped++; continue; }
  const host = hostOf(url);
  seen.add(url);
  const entry = {
    title: String(r?.title || 'Untitled'),
    link: url,
    snippet: String(r?.snippet || ''),
    source_type: retag(host, r?.source_type)
  };
  all.push(entry);
  if (isAllowed(host)) {
    cleaned.push(entry);
  } else {
    dropped++;
  }
}

const order = { city: 1, state: 2, publisher: 3, other: 4 };

// If the domain filter drops everything, fall back to all unique sources
// so the user always sees something rather than "No verified sources".
const useFallback = cleaned.length === 0 && all.length > 0;
const pool = useFallback ? all : cleaned;

pool.sort((a, b) => (order[a.source_type] || 9) - (order[b.source_type] || 9));
const final = pool.slice(0, 6);

return [{
  json: {
    output: {
      executive_summary: ai?.executive_summary || 'No summary available.',
      base_code: ai?.base_code || 'Not identified',
      adopting_authority: ai?.adopting_authority || 'Not identified',
      state_code_reference: ai?.state_code_reference || 'Not specified',
      local_amendments: ai?.local_amendments || 'None found',
      results: final
    },
    filter_stats: {
      input_count: rawResults.length,
      kept: final.length,
      dropped: useFallback ? 0 : dropped,
      used_fallback: useFallback
    },
    intermediateSteps
  }
}];

const formData = $('User Input Form').first().json;
const location = formData['Location'];
const codeType = formData['Code Type'];
const raw = $input.first().json;
const ai = raw?.output ?? raw;

const escape = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');

const safeUrl = (u) => {
  const s = String(u ?? '').trim();
  return /^https?:\/\//i.test(s) ? s : '#';
};

const summary    = escape(ai?.executive_summary || 'No summary available.');
const baseCode   = escape(ai?.base_code || 'Not identified');
const authority  = escape(ai?.adopting_authority || 'Not identified');
const stateRef   = escape(ai?.state_code_reference || 'Not specified');
const amendments = escape(ai?.local_amendments || 'None found');
const results    = Array.isArray(ai?.results) ? ai.results : [];

let sourcesHtml = '';
if (results.length === 0) {
  sourcesHtml = 'No verified sources were returned. Try a more specific location (e.g., add the state) and retry.';
} else {
  const items = results.map((r, i) => {
    const title   = escape(r?.title || 'Untitled source');
    const link    = safeUrl(r?.link);
    const snippet = escape(r?.snippet || '');
    const type    = escape(r?.source_type || 'other');
    return '<li><strong><a href="' + link + '" target="_blank" rel="noopener noreferrer">' + title + '</a></strong>'
      + ' <em>[' + type + ']</em><br>' + snippet + '</li>';
  });
  sourcesHtml = '<ol>' + items.join('') + '</ol>';
}

const html = ''
  + '<a href="/form/building-code-finder">&larr; New Search</a>'
  + '<hr>'
  + '<strong>' + escape(codeType) + ' &mdash; ' + escape(location) + '</strong><br><br>'
  + summary
  + '<hr>'
  + '<strong>KEY ADOPTED CODE</strong><br><br>'
  + '<table width="100%" cellpadding="6" cellspacing="0">'
  + '<tr><td align="right" width="38%"><strong>Base Code</strong></td><td align="left">&nbsp;&nbsp;' + baseCode + '</td></tr>'
  + '<tr><td align="right"><strong>Adopting Authority</strong></td><td align="left">&nbsp;&nbsp;' + authority + '</td></tr>'
  + '<tr><td align="right"><strong>State Reference</strong></td><td align="left">&nbsp;&nbsp;' + stateRef + '</td></tr>'
  + '</table>'
  + '<hr>'
  + '<strong>LOCAL AMENDMENTS</strong><br><br>'
  + amendments
  + '<hr>'
  + '<strong>OFFICIAL SOURCES</strong><br>'
  + sourcesHtml
  + '<hr>'
  + '<small>Generated by AI research agent. Always verify against the official jurisdiction website before relying on this information for permitting or construction decisions.</small>';

return [{
  json: {
    formatted: html,
    metadata: { workflow: 'building-code-lookup', version: '3.0.0', generated_at: new Date().toISOString() }
  }
}];
